```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The contract guarantees len(text) <= 100000, so the reply is sent as given.
        // The confirmation, including the session identity, comes from the host.
        // The node does not fabricate it.
        let confirmation: DeliveryConfirmation = response_channel::send(&reply.text);

        // The output must have delivered == true and a session identity present.
        // If the host's confirmation does not meet that, trap rather than emit a
        // violating value. The send is not retried, because a retry could deliver
        // the reply twice.
        if !confirmation.delivered {
            panic!("response channel did not confirm delivery");
        }
        if confirmation.session.is_empty() {
            panic!("response channel returned no session identity");
        }

        DeliveryConfirmation {
            session: confirmation.session,
            delivered: true,
        }
    }
}

export!(Node);
